const $ = s => document.querySelector(s);
const esc = x => String(x ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money = (n, compact=true) => n == null ? '—' : new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',notation:compact?'compact':'standard',maximumFractionDigits:compact?1:0}).format(n);
const number = n => new Intl.NumberFormat('en-US',{maximumFractionDigits:0}).format(n);
const pct = n => `${(n*100).toFixed(1)}%`;
const state = {view:'overview',category:'',rfqs:[],suppliers:[],scenario:null,rfq:'RFQ-001',preset:'balanced',renderId:0};
const titles = {
  overview:['A clearer view. A stronger sourcing decision.','From fragmented spend to an evidence-backed supplier recommendation.','Executive overview'],
  spend:['See where the opportunity begins.','Inspect spend concentration, contract coverage, and price exceptions.','Spend intelligence'],
  suppliers:['Know the supplier behind the number.','Transparent performance signals, weighted risk, and exposure.','Supplier 360'],
  sourcing:['Turn competing bids into a defensible award.','Normalize terms. Set the constraints. Compare an auditable recommendation.','Sourcing workbench'],
  forecast:['Plan for a range of outcomes.','Backtested monthly spend forecasts with visible uncertainty and assumptions.','Cost outlook'],
  evidence:['Every commercial term has a source.','Search synthetic contracts and inspect exact extraction evidence.','Contract evidence'],
  quality:['Trust starts before the dashboard.','Inspect source controls, quarantined records, and the financial bridge.','Data & controls']
};
async function api(path,opts){const r=await fetch(`/api/v1/${path}`,opts);if(!r.ok){const e=await r.json().catch(()=>({detail:r.statusText}));throw new Error(typeof e.detail==='string'?e.detail:JSON.stringify(e.detail));}return r.json();}
function error(e){$('#error').textContent=e.message;$('#error').hidden=false;}
function metric(label,value,note,tag=''){return `<div class="metric"><div class="metric-label">${label}</div><div class="metric-value">${value}</div><small>${tag?`<span class="tag">${tag}</span>`:''}${note}</small></div>`;}
function panel(title,sub,body,action=''){return `<div class="panel"><div class="panel-heading"><div><h2>${title}</h2><p class="sub">${sub}</p></div>${action}</div>${body}</div>`;}
function table(headers,rows){return `<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function bars(rows){const max=Math.max(...rows.map(r=>r.value),1);return `<div class="bars">${rows.map(r=>`<div class="bar-row"><span>${esc(r.name)}</span><div class="bar-track"><div class="bar-fill" style="width:${r.value/max*100}%"></div></div><span class="bar-value">${money(r.value)}</span></div>`).join('')}</div>`;}
function lineChart(history,future=[]){const vals=[...history.map(x=>x.spend),...future.flatMap(x=>[x.low,x.high])];const max=Math.max(...vals,1)*1.1;const w=640,h=230,p=38;const all=[...history,...future];const x=i=>p+i*(w-2*p)/Math.max(all.length-1,1),y=v=>h-p-v/max*(h-2*p);const path=history.map((v,i)=>`${i?'L':'M'}${x(i)},${y(v.spend)}`).join(' ');const grid=[0,.25,.5,.75,1].map(t=>`<line class="grid" x1="${p}" y1="${y(max*t)}" x2="${w-p}" y2="${y(max*t)}"/><text x="2" y="${y(max*t)+3}">${money(max*t)}</text>`).join('');const ticks=all.filter((_,i)=>i%Math.max(1,Math.floor(all.length/5))===0).map(v=>{const i=all.indexOf(v);return `<text x="${x(i)}" y="${h-10}" text-anchor="middle">${esc(v.month.slice(0,7))}</text>`;}).join('');let band='',futurePath='';if(future.length){band=`<polygon fill="#d9eee3" points="${future.map((v,i)=>`${x(history.length+i)},${y(v.high)}`).join(' ')} ${future.map((v,i)=>`${x(history.length+i)},${y(v.low)}`).reverse().join(' ')}"/>`;futurePath=`<path d="${future.map((v,i)=>`${i?'L':'M'}${x(history.length+i)},${y(v.spend)}`).join(' ')}" class="line" stroke-dasharray="5 4"/>`;}
return `<svg class="chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="Monthly spend trend in US dollars${future.length?' with six-month forecast and illustrative prediction band':''}">${grid}${band}<path d="${path}" class="line"/>${futurePath}${ticks}</svg>`;}
function riskChart(rows){const w=540,h=230,p=38,max=Math.max(...rows.map(s=>s.spend_usd),1)*1.08;return `<svg class="chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="Supplier risk score versus spend exposure">${[0,.5,1].map(t=>`<line class="grid" x1="${p}" y1="${h-p-t*(h-2*p)}" x2="${w-p}" y2="${h-p-t*(h-2*p)}"/><text x="0" y="${h-p-t*(h-2*p)+3}">${money(max*t)}</text>`).join('')}${[0,25,50,75,100].map(v=>`<text x="${p+v/100*(w-2*p)}" y="${h-15}" text-anchor="middle">${v}</text>`).join('')}${rows.map(s=>`<circle cx="${p+s.risk_score/100*(w-2*p)}" cy="${h-p-s.spend_usd/max*(h-2*p)}" r="${5+Math.sqrt(s.spend_usd/max)*10}" fill="${s.risk_score>50?'#c99a54':'#3c9a7f'}" fill-opacity=".65" stroke="white"><title>${esc(s.canonical_name)}: risk ${s.risk_score.toFixed(1)}, spend ${money(s.spend_usd,false)}</title></circle>`).join('')}<text x="${w/2}" y="${h}" text-anchor="middle">Risk score →</text></svg>`;}
async function render(){const ticket=++state.renderId;$('#error').hidden=true;const [title,sub,crumb]=titles[state.view];$('#page-title').textContent=title;$('#page-subtitle').textContent=sub;$('#breadcrumb').textContent=crumb;document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===state.view));$('#category-filter').disabled=['quality','evidence','sourcing'].includes(state.view);$('#content').innerHTML='<div class="loading">Loading the decision workspace…</div>';try{const html=await ({overview:overview,spend:spendView,suppliers:supplierView,sourcing:sourcingView,forecast:forecastView,evidence:evidenceView,quality:qualityView}[state.view])();if(ticket!==state.renderId)return;$('#content').innerHTML=html;bindView();}catch(e){if(ticket===state.renderId){$('#content').innerHTML='<div class="empty">This view could not be loaded.</div>';error(e);}}}
async function overview(){const d=await api(`overview${state.category?'?category_id='+state.category:''}`);state.overview=d;return `<div class="metrics">${metric('Total governed spend',money(d.total_spend),'36-month historical baseline')}${metric('Annual spend',money(d.annual_spend),'Nov 2025 – Oct 2026')}${metric('Off-contract exposure',money(d.off_contract_spend),'Review population · potential overlap')}${metric('On-time delivery',pct(d.on_time_rate),'Observed promised / actual dates')}</div>
<div class="recommendation"><div><span class="overline">NEXT SOURCING DECISION</span><h2>IT Hardware · annual supplier award</h2><p>Compare four normalized bids against capacity, concentration, and qualified-source constraints. See the cost range before recommending an award.</p></div><button class="button" data-go="sourcing">Open sourcing workbench ↗</button></div>
<div class="split">${panel('Where the spend sits','Category spend · governed PO lines',bars(d.category_spend.slice(0,7).map(c=>({name:c.name,value:c.extended_spend_usd}))),'<button class="text-link" data-go="spend">Explore spend →</button>')}${panel('Risk in the context of exposure','Each bubble is one supplier · larger bubble, greater spend',riskChart(d.supplier_risk),'<span class="pill gray">Explainable score</span>')}</div>
${panel('Priority sourcing events','Illustrative bid opportunities · savings require scenario evaluation',table(['Sourcing event','Category','Demand','Baseline cost','Decision'],filteredRfqs().slice(0,4).map(r=>[`<strong>${esc(r.rfq_id)}</strong><small>${esc(r.title)}</small>`,esc(r.name),`${number(r.demand)} EA`,money(r.demand*r.baseline_unit_price),`<button class="text-link" data-rfq="${r.rfq_id}">Compare bids →</button>`])))}<div class="notes"><strong>Evidence basis</strong> · ${number(d.pipeline.published_rows)} published PO lines · ${d.pipeline.quarantined_rows} quarantined · financial bridge ${money(d.pipeline.reconciliation_delta_usd,false)} · All savings are simulated; off-contract and anomaly exposure are not realized savings.</div>`;}
function filteredRfqs(){return state.rfqs.filter(r=>!state.category||r.category_id===Number(state.category));}
async function spendView(){const d=await api(`overview${state.category?'?category_id='+state.category:''}`);return `<div class="metrics">${metric('Governed PO spend',money(d.total_spend),`${number(d.po_lines)} reconciled lines`)}${metric('Off-contract exposure',money(d.off_contract_spend),pct(d.off_contract_spend/d.total_spend)+' of spend')}${metric('Price anomaly exposure',money(d.anomaly_spend),'Item-level robust z-score > 3.5')}${metric('Active suppliers',number(d.supplier_count),'Deterministic alias matching')}</div><div class="split">${panel('Category spend distribution','Use the category filter to inspect one sourcing area',bars(d.category_spend.map(c=>({name:c.name,value:c.extended_spend_usd}))))}${panel('Spend through time','Monthly nominal USD · historical synthetic transactions',lineChart(d.monthly_spend.map(m=>({month:m.month,spend:m.extended_spend_usd}))))}</div>${panel('Supplier concentration','Largest exposures first · within selected category',table(['Supplier','Category','Spend','Category share','Risk score'],d.supplier_risk.sort((a,b)=>b.spend_usd-a.spend_usd).slice(0,15).map(s=>[`<button class="text-link" data-supplier="${s.supplier_id}">${esc(s.canonical_name)}</button>`,esc(categoryName(s.category_id)),money(s.spend_usd),pct(s.concentration),s.risk_score.toFixed(1)])))}<div class="notes"><strong>Method</strong> · Supplier names resolve through explicit aliases. FX is a fixed synthetic USD/EUR/GBP schedule. Anomalies use item-level median absolute deviation. Exposure categories overlap and must not be added as savings.</div>`;}
function categoryName(id){return state.categories.find(c=>c.category_id===id)?.name||id;}
async function supplierView(){const rows=state.suppliers.filter(s=>!state.category||s.category_id===Number(state.category));return `${panel('Supplier risk × spend','Risk score 0–100 · a project policy, not a calibrated default probability',riskChart(rows))}${panel('Supplier performance directory','Select a supplier to inspect the score components and denominators',table(['Supplier','Spend','On-time','Defect rate','Response median','Risk score'],rows.map(s=>[`<button class="text-link" data-supplier="${s.supplier_id}">${esc(s.canonical_name)}</button><small>${esc(s.country)} · ${esc(categoryName(s.category_id))}</small>`,money(s.spend_usd),pct(s.on_time_rate),pct(s.defect_rate),`${s.response_hours_p50.toFixed(1)}h`,`<span class="pill ${s.risk_score>50?'amber':''}">${s.risk_score.toFixed(1)} / 100</span>`])))}<div class="notes">Score weights: late delivery 30%, defect 20%, price volatility 15%, capacity utilization 15%, response SLA excess 10%, concentration 10%. Capacity utilization is a disclosed synthetic 72% assumption. Response is assessed relative to the requested SLA.</div>`;}
async function sourcingView(){const rfq=state.rfqs.find(r=>r.rfq_id===state.rfq)||state.rfqs[0];state.rfq=rfq.rfq_id;const bids=await api(`rfqs/${rfq.rfq_id}/bids`);return `<div class="panel"><div class="panel-heading"><div><h2>Annual sourcing event</h2><p class="sub">Normalized to USD per each · fixed synthetic FX rates</p></div><select id="rfq-select" aria-label="Sourcing event">${state.rfqs.map(r=>`<option value="${r.rfq_id}" ${r.rfq_id===rfq.rfq_id?'selected':''}>${r.rfq_id} · ${esc(r.name)}</option>`).join('')}</select></div>${table(['Supplier','Original quote','USD / EA','Logistics / EA','Capacity','Risk','Evidence'],bids.map(b=>[esc(b.canonical_name),`${money(b.quoted_price,false).replace('$',esc(b.currency)+' ')} / ${b.uom}`,money(b.unit_price_usd,false),money(b.logistics_unit_usd,false),number(b.capacity),b.risk_score.toFixed(1),`<button class="text-link" data-document="${b.contract_id}">${b.contract_id} ↗</button>`]))}</div>
<div class="panel"><div class="panel-heading"><div><h2>Design the award scenario</h2><p class="sub">Continuous allocation MILP · qualified-source policy is an explicit scenario assumption</p></div><span class="pill gray">Human review required</span></div><div class="segmented" aria-label="Scenario preset"><button data-preset="cost">Lowest cost</button><button class="active" data-preset="balanced">Balanced</button><button data-preset="resilient">Resilience first</button></div><form id="scenario-form"><div class="scenario-controls"><label>Required demand (EA)<input id="demand" type="number" min="1" max="10000000" value="${rfq.demand}" required></label><label>Maximum supplier share (%)<input id="max-share" type="number" min="10" max="100" value="60" required></label><label>Risk penalty (USD / risk unit / EA)<input id="risk-penalty" type="number" min="0" max="10000" value="100" required></label><label>Minimum qualified allocation (%)<input id="qualified" type="number" min="0" max="100" value="30" required></label><label>Minimum suppliers<input id="min-suppliers" type="number" min="1" max="4" value="2" required></label><label>Maximum suppliers<input id="max-suppliers" type="number" min="1" max="4" value="3" required></label><label>Available capacity multiplier<input id="capacity" type="number" step=".1" min=".1" max="2" value="1" required></label><label>Logistics cost multiplier<input id="logistics" type="number" step=".1" min="0" max="5" value="1" required></label></div><button type="submit" class="button" id="run-scenario">Run award optimization →</button></form><div class="notes">Risk penalty is an objective preference, not a cash expense. The baseline is an explicitly synthetic RFQ reference price at the same demand. Awards are recommendations only.</div></div><div id="scenario-results"><div class="empty">Run a scenario to see the allocation, financial bridge, and uncertainty.</div></div>`;}
function scenarioHTML(s){if(s.status!=='Optimal')return panel('Scenario infeasible','No award recommendation generated',`<div class="error">${esc(s.message)}</div><p>Reduce demand, relax concentration, or revisit capacity and qualification constraints.</p>`);const colors=['#0c7c68','#6f9b75','#b7ac76','#8b99a9'];return `<div class="metrics">${metric('Baseline annual cost',money(s.baseline_cost),'Reference price × scenario demand')}${metric('Recommended landed cost',money(s.landed_cost),'Purchase + logistics + fixed costs')}${metric('Simulated cash savings',money(s.savings),pct(s.savings_pct)+' below baseline')}${metric('P10–P90 landed cost',`${money(s.uncertainty.cost_p10)}–${money(s.uncertainty.cost_p90)}`,`${number(s.uncertainty.draws)} Monte Carlo draws`)}</div>${panel('Recommended supplier allocation','Subject to commercial validation and human approval',`<div class="allocation">${s.allocations.map((a,i)=>`<div style="width:${a.share*100}%;background:${colors[i]}">${pct(a.share)}</div>`).join('')}</div>${table(['Supplier','Award units','Share','Landed cost','Risk'],s.allocations.map(a=>[esc(a.name),number(a.quantity),pct(a.share),money(a.cost),a.risk_score.toFixed(1)]))}<div class="check-grid">${Object.entries(s.constraint_checks).map(([k,v])=>`<span class="pill ${v?'':'amber'}">${v?'✓':'!'} ${esc(k.replaceAll('_',' '))}</span>`).join('')}</div>`)}<div class="split">${panel('From baseline to recommendation','Cash costs reconcile; risk preference is shown separately',table(['Component','USD'],[['Baseline',money(s.baseline_cost,false)],['Purchase',money(s.objective_components.purchase,false)],['Logistics',money(s.objective_components.logistics,false)],['Supplier fixed costs',money(s.objective_components.fixed,false)],['Recommended cash cost',`<strong>${money(s.landed_cost,false)}</strong>`],['Risk objective penalty (noncash)',money(s.objective_components.risk_penalty,false)],['Optimization objective',money(s.objective_value,false)]]))}${panel('Cost uncertainty','Fixed award mix · correlated demand and price shocks',histogram(s.uncertainty.histogram)+`<div class="legend"><span>P10 ${money(s.uncertainty.cost_p10)}</span><span>P50 ${money(s.uncertainty.cost_p50)}</span><span>P90 ${money(s.uncertainty.cost_p90)}</span></div><p class="sub">${esc(s.uncertainty.method)}</p>`)}</div>${panel('Decision receipt','Inputs, solver, and source snapshot travel with every recommendation',`<div class="receipt">Scenario: ${s.scenario_id}<br>Status: ${s.status} · ${s.solver}<br>Input hash: ${s.input_hash}<br>Snapshot: ${s.input_snapshot_id}<br>Approval: human review required</div><div style="margin-top:15px"><button class="button secondary" id="download-scenario">↓ Download decision receipt</button></div>`)}`;}
function histogram(rows){const max=Math.max(...rows.map(r=>r.count));return `<svg class="chart small-chart" viewBox="0 0 500 180" role="img" aria-label="Monte Carlo landed cost distribution">${rows.map((r,i)=>`<rect x="${25+i*16}" y="${145-r.count/max*120}" width="14" height="${r.count/max*120}" fill="#5a9b7b"><title>${money(r.cost,false)}: ${r.count} draws</title></rect>`).join('')}<text x="25" y="170">${money(rows[0].cost)}</text><text x="460" y="170" text-anchor="end">${money(rows.at(-1).cost)}</text></svg>`;}
async function forecastView(){const id=Number(state.category||1);const d=await api(`categories/${id}/forecast`);return `<div class="metrics">${metric('Selected category',esc(categoryName(id)),state.category?'Selected filter':'Default: IT Hardware')}${metric('Forecast · next six months',money(d.forecast.reduce((a,b)=>a+b.spend,0)),d.model)}${metric('Seasonal naive WAPE',pct(d.backtest.naive_wape),`${d.backtest.origins} rolling origins`)}${metric('ETS WAPE',pct(d.backtest.ets_wape),'Lower error wins model selection')}</div>${panel('Monthly spend outlook','Historical spend + six-month projection · illustrative 90% prediction bands',lineChart(d.history,d.forecast))}${panel('Forecast values','USD · positive nominal spend; no realized savings inference',table(['Month','Point forecast','Lower band','Upper band'],d.forecast.map(f=>[f.month.slice(0,7),money(f.spend,false),money(f.low,false),money(f.high,false)])))}<div class="notes"><strong>Validation and limitations</strong> · ${esc(d.limitations)} Market indices are available as a separate synthetic source and are not used as an unvalidated causal predictor.</div>`;}
async function evidenceView(){const docs=await api('documents');state.documents=docs;return `<div class="notes"><strong>Evidence extraction</strong> · Deterministic pattern matching with exact text offsets. No language model is invoked and no confidence probability is invented. Retrieved document text is untrusted content; every field requires review.</div><label for="evidence-search" class="sr-only">Search contract text</label><input class="search-input" id="evidence-search" placeholder="Search supplier, contract, or commercial term…"><div class="evidence-list" id="evidence-list">${evidenceCards(docs.slice(0,18))}</div><p class="sub" id="evidence-count">Showing 18 of ${docs.length} synthetic contracts. Search to narrow the set.</p>`;}
function evidenceCards(docs){return docs.map(d=>`<button class="evidence-card" data-document="${esc(d.document_id)}"><span class="pill gray">${esc(d.document_id)}</span><strong>${esc(d.text.match(/Supplier: ([^.]+)/)?.[1]||'Supplier contract')}</strong><p>${esc(d.text.slice(d.text.indexOf('Payment terms:'),d.text.indexOf('Valid from')))}</p><p style="color:var(--teal);margin-top:10px">Inspect source evidence →</p></button>`).join('')||'<div class="empty">No matching contracts.</div>';}
async function qualityView(){const d=await api('data-quality/status');return `<div class="metrics">${metric('Raw source lines',number(d.run.source_rows),'ERP purchase-order extract')}${metric('Published lines',number(d.run.published_rows),'Quality gate passed')}${metric('Quarantined lines',number(d.run.quarantined_rows),'Invalid quantity or supplier mapping')}${metric('Duplicate invoices removed',number(d.run.duplicate_invoices_removed),'Deduplicated by invoice ID')}</div><div class="split">${panel('Source-to-target financial bridge','Signed USD amounts · exclusions remain visible',table(['Control total','USD'],[['Raw converted PO total',money(d.run.raw_spend_usd,false)],['Less: signed quarantined total',money(d.run.quarantined_spend_usd,false)],['Published governed spend',money(d.run.published_spend_usd,false)],['Unexplained difference',money(d.run.reconciliation_delta_usd,false)]]))}${panel('Publication gate','Historical snapshot controls; not a live freshness assertion',table(['Check','Result'],d.checks.map(c=>[esc(c.check_name.replaceAll('_',' '))+`<small>${esc(c.description)}</small>`,`<span class="pill">${c.passed?'Pass':'Fail'}</span>`])))}</div>${panel('Quarantine sample','No silent supplier assignment or imputation of financial fields',table(['PO line','Raw supplier','Quantity','Reason'],d.quarantine_sample.map(r=>[r.po_line_id,esc(r.supplier_raw),r.quantity,esc(r.quarantine_reason)])))}${panel('Lineage and reproducibility','Raw extracts → normalization → quarantine gate → analytical marts → decision model',`<div class="receipt">Run: ${d.run.run_id}<br>Input snapshot: ${d.run.input_snapshot_id}<br>Executed: ${esc(d.run.timestamp)}<br>Execution mode: ${esc(d.run.mode)}<br>Snapshot date: ${d.run.snapshot_date}<br>${esc(d.freshness_basis)}</div>`)}`;}
function bindView(){document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>navigate(b.dataset.go));document.querySelectorAll('[data-rfq]').forEach(b=>b.onclick=()=>{state.rfq=b.dataset.rfq;navigate('sourcing');});bindDetails();if($('#scenario-form')){$('#scenario-form').onsubmit=runScenario;$('#rfq-select').onchange=e=>{state.rfq=e.target.value;render();};document.querySelectorAll('[data-preset]').forEach(b=>b.onclick=()=>applyPreset(b.dataset.preset));}if($('#evidence-search'))$('#evidence-search').oninput=e=>{const docs=state.documents.filter(d=>d.text.toLowerCase().includes(e.target.value.toLowerCase()));$('#evidence-list').innerHTML=evidenceCards(docs.slice(0,30));$('#evidence-count').textContent=`Showing ${Math.min(docs.length,30)} of ${docs.length} matching contracts`;bindDetails();};}
function bindDetails(){document.querySelectorAll('[data-supplier]').forEach(b=>b.onclick=()=>supplierDetail(Number(b.dataset.supplier)));document.querySelectorAll('[data-document]').forEach(b=>b.onclick=()=>documentDetail(b.dataset.document));}
function applyPreset(p){state.preset=p;const presets={cost:[0,70,20,1],balanced:[100,60,30,2],resilient:[400,45,60,3]};const [risk,share,qualified,min]=presets[p];$('#risk-penalty').value=risk;$('#max-share').value=share;$('#qualified').value=qualified;$('#min-suppliers').value=min;document.querySelectorAll('[data-preset]').forEach(b=>b.classList.toggle('active',b.dataset.preset===p));}
async function runScenario(e){e.preventDefault();const button=$('#run-scenario');button.disabled=true;button.textContent='Solving and simulating…';$('#error').hidden=true;const params={demand:Number($('#demand').value),max_share:Number($('#max-share').value)/100,risk_penalty:Number($('#risk-penalty').value),qualified_share:Number($('#qualified').value)/100,min_suppliers:Number($('#min-suppliers').value),max_suppliers:Number($('#max-suppliers').value),capacity_factor:Number($('#capacity').value),logistics_factor:Number($('#logistics').value)};try{state.scenario=await api(`rfqs/${state.rfq}/scenarios`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(params)});$('#scenario-results').innerHTML=scenarioHTML(state.scenario);if($('#download-scenario'))$('#download-scenario').onclick=()=>downloadJSON(state.scenario,`${state.scenario.scenario_id}.json`);}catch(err){error(err);}finally{button.disabled=false;button.textContent='Run award optimization →';}}
function downloadJSON(value,name){const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function openDetail(title,body){$('#dialog-title').textContent=title;$('#dialog-body').innerHTML=body;$('#detail-dialog').showModal();}
async function supplierDetail(id){try{const s=await api(`suppliers/${id}/scorecard`);const weights={late:.3,defect:.2,volatility:.15,capacity:.15,response:.1,concentration:.1};openDetail(s.canonical_name,`<div class="metrics" style="grid-template-columns:1fr 1fr">${metric('Spend exposure',money(s.spend_usd),`${number(s.po_lines)} PO lines`)}${metric('Risk score',s.risk_score.toFixed(1),'Weighted project policy')}</div><div class="risk-components">${Object.entries(weights).map(([k,w])=>`<div class="bar-row"><span>${esc(k)} (${w*100}%)</span><div class="bar-track"><div class="bar-fill" style="width:${s['risk_'+k]*100}%"></div></div><span>${(s['risk_'+k]*w*100).toFixed(1)}</span></div>`).join('')}</div><div class="notes">On-time denominator: ${number(s.delivered)} observed deliveries. Defect denominator: ${number(s.units)} units. Capacity utilization is a synthetic assumption of 72%; validate before commercial use.</div>`);}catch(e){error(e);}}
async function documentDetail(id){try{const d=await api(`documents/${id}/evidence`);openDetail(id,`<p class="dialog-copy">${esc(d.text)}</p>${table(['Field','Value','Exact source text'],Object.entries(d.extraction.fields).map(([k,v])=>[esc(k.replaceAll('_',' ')),esc(v.value),`${esc(v.evidence||'No match')}<small>Offsets ${v.start??'—'}–${v.end??'—'} · review required</small>`]))}<div class="notes">${esc(d.extraction.mode)}. ${esc(d.extraction.trust_policy)}</div>`);}catch(e){error(e);}}
function navigate(view){state.view=view;location.hash=view;render();}
document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>navigate(b.dataset.view));$('#category-filter').onchange=e=>{state.category=e.target.value;render();};$('#close-dialog').onclick=()=>$('#detail-dialog').close();$('#export-btn').onclick=()=>{if(state.view==='sourcing'&&state.scenario)return downloadJSON(state.scenario,'source360-decision.json');const dataset={quality:'dq_results',forecast:'monthly_spend',sourcing:'rfq_bids'}[state.view]||'supplier_metrics';location.href=`/api/v1/export/${dataset}`;};
window.addEventListener('hashchange',()=>{const view=location.hash.slice(1);if(titles[view]&&view!==state.view){state.view=view;render();}});
(async()=>{try{[state.categories,state.rfqs,state.suppliers]=await Promise.all([api('categories'),api('rfqs'),api('suppliers')]);$('#category-filter').innerHTML='<option value="">All categories</option>'+state.categories.map(c=>`<option value="${c.category_id}">${esc(c.name)}</option>`).join('');state.view=titles[location.hash.slice(1)]?location.hash.slice(1):'overview';await render();}catch(e){error(e);}})();
